package com.cognia.api.adapter.out.persistence;
import jakarta.persistence.Entity; import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="actividad") public class ActivityJpaEntity { @Id private UUID id; @Column(name="concepto_id") private UUID conceptId; @Column(name="codigo") private String code; @Column(name="enunciado") private String statement; @Column(name="retroalimentacion") private String feedback; @Column(name="dificultad") private int difficulty; @Column(name="uso") private String usage; @Column(name="tipo") private String type; @Column(name="activa") private boolean active; protected ActivityJpaEntity(){} public UUID getId(){return id;} public UUID getConceptId(){return conceptId;} public String getCode(){return code;} public String getStatement(){return statement;} public String getFeedback(){return feedback;} public int getDifficulty(){return difficulty;} public String getUsage(){return usage;} public String getType(){return type;} public boolean isActive(){return active;} }
